// Edge Research referee R1 EmaCross (DESIGN §4.5 item 2): EURUSD m15, IC, cTrader backtest with tick data.
// EMA 20 / 50 cross on closes: buy on the cross up, sell on the cross down (the opposite position is closed at the same bar close), stop 2 ATR, no target.
// Generated by tests/referees/make_cbots.py; the same rules as tests/referees/referees.py, the conventions of
// cTrader-Bots/CONVENTIONS.md. Backtest only: it never runs on a live or prop account.
// Output: ~/cAlgo/Exports/referees/R1_<SYMBOL>_<Seed Date>.csv, one row per closed position, a summary row at the end.
// Start the backtest ON the Seed Date (indicators are seeded on its first bar), end it on 2024-06-30.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using cAlgo.API;
using cAlgo.API.Internals;

namespace cAlgo.Robots
{
    [Robot(TimeZone = TimeZones.UTC, AccessRights = AccessRights.FullAccess)]
    public class ER_R1_EmaCross : Robot
    {
        [Parameter("Seed Date (UTC, yyyy-MM-dd)", DefaultValue = "2023-12-01")] public string SeedDate { get; set; }
        [Parameter("Trade From (UTC, yyyy-MM-dd)", DefaultValue = "2024-01-01")] public string TradeFrom { get; set; }
        [Parameter("Lots", DefaultValue = 1.0, MinValue = 0.01)] public double Lots { get; set; }
        [Parameter("Output Folder (empty = ~/cAlgo/Exports/referees)", DefaultValue = "")] public string OutputFolder { get; set; }

        private const string RefId = "R1";
        private const string Label = "ER-R1";
        private const int Warmup = 100;            // closed bars after the seed bar before any decision
        private const long TfMs = 900000L;
        private const long HoldMs = 0L;            // time exit after the fill; 0 = none
        private const long ExpiryMs = 0L;          // pending order life from going live; 0 = until the next bar close
        private const bool UseFlats = false;
        private static readonly CultureInfo Inv = CultureInfo.InvariantCulture;
        private static readonly DateTime Epoch = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc);

        private long _seedMs, _fromMs;
        private double _tick, _p10, _volume;
        private bool _stopping;
        private TimeZoneInfo _ny;
        private StreamWriter _out;
        private readonly List<long> _openMs = new List<long>();
        private readonly List<double> _o = new List<double>(), _h = new List<double>(), _l = new List<double>(), _c = new List<double>();
        private readonly List<double> _tr = new List<double>(), _atr = new List<double>();
        private readonly Dictionary<int, long> _liveMs = new Dictionary<int, long>(), _fillMs = new Dictionary<int, long>(), _barMs = new Dictionary<int, long>();
        private readonly Dictionary<int, double> _sl0 = new Dictionary<int, double>(), _tp0 = new Dictionary<int, double>();
        private readonly Dictionary<int, string> _why = new Dictionary<int, string>();
        private long _pendLiveMs = -1, _pendEndMs = -1, _pendBarMs = -1;
        private int _trades, _droppedBusy, _refusedCrossed, _expired, _cancelledFlat, _errors;
        private readonly List<double> _fast = new List<double>(), _slow = new List<double>();

        protected override void OnStart()
        {
            _seedMs = DayMs(SeedDate);
            _fromMs = DayMs(TradeFrom);
            _tick = Symbol.TickSize;
            _p10 = Math.Pow(10, Symbol.Digits);
            _volume = Symbol.NormalizeVolumeInUnits(Symbol.QuantityToVolumeInUnits(Lots));
            _ny = FindNy();
            string root = string.IsNullOrWhiteSpace(OutputFolder)
                ? Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "cAlgo", "Exports", "referees")
                : OutputFolder.Trim();
            Directory.CreateDirectory(root);
            string path = Path.Combine(root, string.Format(Inv, "{0}_{1}_{2}.csv", RefId, SymbolName, SeedDate));
            _out = new StreamWriter(path, false) { AutoFlush = true };
            _out.WriteLine("ref,symbol,side,bar_open_ms,live_ms,fill_ms,entry_ms,entry_px,sl0,tp0,exit_ms,exit_px,exit_kind,volume,gross,commission,swap,net");
            Positions.Opened += OnOpened;
            Positions.Closed += OnClosed;
            PendingOrders.Filled += OnFilled;
            Print("{0} {1} on {2}: writing {3}", RefId, "EmaCross", SymbolName, path);
            if (Bars.TimeFrame != TimeFrame.Minute15) Problem("the chart timeframe is " + Bars.TimeFrame + "; this referee needs m15");
            if (SymbolName != "EURUSD") Problem("the symbol is " + SymbolName + "; this referee is for EURUSD");
            if (Ms(Server.Time) > _seedMs + 86400000L) Problem("the backtest starts after the Seed Date: start it on " + SeedDate);
            if (Math.Abs(_tick * _p10 - 1) > 1e-9) Problem("the tick size is not 10^-digits");
        }

        protected override void OnBarClosed()
        {
            Housekeeping(true);
            int idx = Bars.Count - 1;          // in OnBarClosed, Bars excludes the new live bar: the last item is the bar that closed
            if (idx < 0) return;
            long op = Ms(Bars.OpenTimes[idx]);
            if (op < _seedMs || (_openMs.Count > 0 && op <= _openMs[_openMs.Count - 1])) return;
            _openMs.Add(op);
            _o.Add(Bars.OpenPrices[idx]);
            _h.Add(Bars.HighPrices[idx]);
            _l.Add(Bars.LowPrices[idx]);
            _c.Add(Bars.ClosePrices[idx]);
            int i = _openMs.Count - 1;
            UpdateAtr(i);
            Calc(i);
            long closeMs = op + TfMs;
            foreach (var p in Positions.FindAll(Label, SymbolName))
                if (FillOf(p) < closeMs) BarEvent(i, p);           // never on the tick the position was filled on, or later
            if (i >= Warmup && op >= _fromMs) Decide(i);
        }

        protected override void OnTick()
        {
            Housekeeping(false);
        }

        protected override void OnStop()
        {
            _stopping = true;
            if (_out == null) return;
            _out.WriteLine(string.Format(Inv, "#summary,{0},trades={1},dropped_busy={2},refused_crossed={3},expired={4},cancelled_flat={5},errors={6},open_at_end={7}",
                RefId, _trades, _droppedBusy, _refusedCrossed, _expired, _cancelledFlat, _errors, Positions.FindAll(Label, SymbolName).Length));
            _out.Flush();
        }

        // ---------------- the rules of R1 ----------------
        private void Calc(int i)
        {
            double kf = 2.0 / (20 + 1), ks = 2.0 / (50 + 1);
            _fast.Add(i == 0 ? _c[i] : _fast[i - 1] + kf * (_c[i] - _fast[i - 1]));
            _slow.Add(i == 0 ? _c[i] : _slow[i - 1] + ks * (_c[i] - _slow[i - 1]));
        }

        private bool Up(int i) { return i >= 1 && _fast[i] > _slow[i] && _fast[i - 1] <= _slow[i - 1]; }
        private bool Dn(int i) { return i >= 1 && _fast[i] < _slow[i] && _fast[i - 1] >= _slow[i - 1]; }

        private void BarEvent(int i, Position p)
        {
            if (i < Warmup || _openMs[i] < _fromMs) return;
            if (Up(i) && p.TradeType == TradeType.Sell) Close(p, "signal");
            else if (Dn(i) && p.TradeType == TradeType.Buy) Close(p, "signal");
        }

        private bool Intent(int i, out int side, out int otype, out double price, out double slDist, out double tpDist)
        {
            side = 0; otype = 0; price = double.NaN; slDist = double.NaN; tpDist = double.NaN;
            bool up = Up(i), dn = Dn(i);
            if (!up && !dn) return false;
            side = up ? 1 : -1;
            slDist = Rt(2.0 * _atr[i]);
            return true;
        }

        private long LastFlatAtOrBefore(long nowMs) { return -1; }    // no flat times in this referee

        // ---------------- shared plumbing (identical in every referee) ----------------
        private void UpdateAtr(int i)          // Wilder 14: first value = mean of the first 14 true ranges; seed bar TR = high - low
        {
            double tr = i == 0 ? _h[i] - _l[i] : Math.Max(_h[i] - _l[i], Math.Max(Math.Abs(_h[i] - _c[i - 1]), Math.Abs(_l[i] - _c[i - 1])));
            _tr.Add(tr);
            double a = double.NaN;
            if (i == 13) { double acc = 0.0; for (int j = 0; j <= i; j++) acc += _tr[j]; a = acc / 14; }
            else if (i > 13) a = (_atr[i - 1] * 13 + _tr[i]) / 14;
            _atr.Add(a);
        }

        private double Sma(List<double> x, int i, int n)
        {
            if (i < n - 1) return double.NaN;
            double acc = 0.0;
            for (int j = i - n + 1; j <= i; j++) acc += x[j];
            return acc / n;
        }

        private double Std(List<double> x, int i, int n, double mean)
        {
            if (i < n - 1) return double.NaN;
            double acc = 0.0;
            for (int j = i - n + 1; j <= i; j++) { double d = x[j] - mean; acc += d * d; }
            return Math.Sqrt(acc / n);
        }

        private double Rt(double x)            // onto the tick grid: n / 10^digits, the nearest double (Python: Grid.rt)
        {
            return Math.Floor(x / _tick + 0.5) / _p10;
        }

        private double Send(double gridPrice)  // a price sent to cTrader: n + 1/4 tick, so cTrader's truncation (RULES A20) or rounding stores n
        {
            return (Math.Floor(gridPrice / _tick + 0.5) + 0.25) / _p10;
        }

        private void Decide(int i)
        {
            int side, otype;
            double price, slDist, tpDist;
            if (!Intent(i, out side, out otype, out price, out slDist, out tpDist)) return;
            if (Positions.FindAll(Label, SymbolName).Length > 0 || PendingOrders.Any(x => x.Label == Label && x.SymbolName == SymbolName)) { _droppedBusy++; return; }
            if (!(slDist > 0)) return;
            var tt = side > 0 ? TradeType.Buy : TradeType.Sell;
            double? slPips = slDist / Symbol.PipSize;
            double? tpPips = tpDist > 0 ? tpDist / Symbol.PipSize : (double?)null;
            long now = Ms(Server.Time);
            string comment = _openMs[i].ToString(Inv);
            if (otype == 0)
            {
                var r = ExecuteMarketOrder(tt, SymbolName, _volume, Label, slPips, tpPips, comment);
                if (!r.IsSuccessful) { Err("market order", r.Error.ToString()); return; }
                Track(r.Position.Id, now, now, _openMs[i]);
                return;
            }
            bool crossed = otype == 1 ? (side > 0 ? Symbol.Ask >= price : Symbol.Bid <= price)
                                      : (side > 0 ? Symbol.Ask <= price : Symbol.Bid >= price);
            if (crossed) { _refusedCrossed++; return; }
            _pendLiveMs = now;
            _pendEndMs = ExpiryMs > 0 ? now + ExpiryMs : -1;
            _pendBarMs = _openMs[i];
            TradeResult res = otype == 1
                ? PlaceStopOrder(tt, SymbolName, _volume, Send(price), Label, slPips, tpPips, ProtectionType.Relative, null, comment)
                : PlaceLimitOrder(tt, SymbolName, _volume, Send(price), Label, slPips, tpPips, ProtectionType.Relative, null, comment);
            if (!res.IsSuccessful) Err("pending order", res.Error.ToString());
        }

        private void Housekeeping(bool barClose)   // after the order engine, before the bar-close rules: flat time, expiry, time exit
        {
            long now = Ms(Server.Time);
            foreach (var p in Positions.FindAll(Label, SymbolName))
            {
                if (UseFlats && FlatDue(LiveOf(p), now)) { Close(p, "flat"); continue; }
                if (HoldMs > 0 && now >= FillOf(p) + HoldMs) Close(p, "time");
            }
            foreach (var po in PendingOrders.Where(x => x.Label == Label && x.SymbolName == SymbolName).ToList())
            {
                if (UseFlats && FlatDue(_pendLiveMs, now)) { CancelPendingOrder(po); _cancelledFlat++; }
                else if (ExpiryMs > 0 ? now >= _pendEndMs : barClose) { CancelPendingOrder(po); _expired++; }
            }
        }

        private bool Trail(Position p, double cand)   // cand on the grid; tighten only, by more than half a tick; beaten -> close now
        {
            if (double.IsNaN(cand) || !p.StopLoss.HasValue) return false;
            double cur = p.StopLoss.Value;
            bool buy = p.TradeType == TradeType.Buy;
            if (buy ? !(cand > cur + _tick / 2) : !(cand < cur - _tick / 2)) return false;
            if (buy ? Symbol.Bid <= cand : Symbol.Ask >= cand) { Close(p, "trail"); return true; }
            var r = ModifyPosition(p, Send(cand), p.TakeProfit, ProtectionType.Absolute);
            if (!r.IsSuccessful) Err("trail", r.Error.ToString());
            return false;
        }

        private bool FlatDue(long liveMs, long nowMs)
        {
            long f = LastFlatAtOrBefore(nowMs);
            return f >= 0 && f >= liveMs;
        }

        private void Close(Position p, string why)
        {
            _why[p.Id] = why;
            var r = ClosePosition(p);
            if (!r.IsSuccessful) Err("close " + why, r.Error.ToString());
        }

        private void Track(int id, long live, long fill, long bar)
        {
            _liveMs[id] = live;
            _fillMs[id] = fill;
            _barMs[id] = bar;
        }

        private long LiveOf(Position p) { long v; return _liveMs.TryGetValue(p.Id, out v) ? v : Ms(p.EntryTime); }
        private long FillOf(Position p) { long v; return _fillMs.TryGetValue(p.Id, out v) ? v : Ms(p.EntryTime); }

        private void OnFilled(PendingOrderFilledEventArgs a)
        {
            if (a.PendingOrder.Label != Label) return;
            Track(a.Position.Id, _pendLiveMs, Ms(Server.Time), _pendBarMs);
        }

        private void OnOpened(PositionOpenedEventArgs a)
        {
            var p = a.Position;
            if (p.Label != Label) return;
            _sl0[p.Id] = p.StopLoss.HasValue ? p.StopLoss.Value : double.NaN;
            _tp0[p.Id] = p.TakeProfit.HasValue ? p.TakeProfit.Value : double.NaN;
        }

        private void OnClosed(PositionClosedEventArgs a)
        {
            var p = a.Position;
            if (p.Label != Label || _out == null) return;
            _trades++;
            string why;
            string kind = a.Reason == PositionCloseReason.StopLoss ? "StopLoss"
                        : a.Reason == PositionCloseReason.TakeProfit ? "TakeProfit"
                        : a.Reason == PositionCloseReason.Closed ? "Closed:" + (_why.TryGetValue(p.Id, out why) ? why : (_stopping ? "end" : "?"))
                        : a.Reason.ToString();
            var h = History.FirstOrDefault(x => x.PositionId == p.Id);
            double exitPx = h != null ? h.ClosingPrice : (p.TradeType == TradeType.Buy ? Symbol.Bid : Symbol.Ask);
            long v;
            _out.WriteLine(string.Join(",", new[] {
                RefId, SymbolName, p.TradeType == TradeType.Buy ? "1" : "-1",
                (_barMs.TryGetValue(p.Id, out v) ? v : -1).ToString(Inv), LiveOf(p).ToString(Inv), FillOf(p).ToString(Inv),
                Ms(p.EntryTime).ToString(Inv), R(p.EntryPrice), R(_sl0.ContainsKey(p.Id) ? _sl0[p.Id] : double.NaN),
                R(_tp0.ContainsKey(p.Id) ? _tp0[p.Id] : double.NaN), Ms(Server.Time).ToString(Inv), R(exitPx), kind,
                R(p.VolumeInUnits), R(p.GrossProfit), R(p.Commissions), R(p.Swap), R(p.NetProfit) }));
        }

        private void Err(string what, string error)
        {
            _errors++;
            Print("ERROR {0}: {1}", what, error);
            if (_out != null) _out.WriteLine("#error," + RefId + "," + Ms(Server.Time).ToString(Inv) + "," + what + "," + error);
        }

        private void Problem(string msg)
        {
            Err("setup", msg);
            Stop();
        }

        private DateTime NyOf(long ms) { return TimeZoneInfo.ConvertTimeFromUtc(FromMs(ms), _ny); }
        private static string R(double x) { return double.IsNaN(x) ? "" : x.ToString("R", Inv); }
        private static long Ms(DateTime t) { return (DateTime.SpecifyKind(t, DateTimeKind.Utc).Ticks - Epoch.Ticks) / 10000; }
        private static DateTime FromMs(long ms) { return new DateTime(Epoch.Ticks + ms * 10000, DateTimeKind.Utc); }
        private static long DayMs(string day)
        {
            return Ms(DateTime.ParseExact(day.Trim(), "yyyy-MM-dd", Inv, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal));
        }

        private static TimeZoneInfo FindNy()
        {
            try { return TimeZoneInfo.FindSystemTimeZoneById("America/New_York"); }
            catch (TimeZoneNotFoundException) { return TimeZoneInfo.FindSystemTimeZoneById("Eastern Standard Time"); }
        }
    }
}
